<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Snake</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #080b10;
      --panel: #111720;
      --border: #293342;
      --text: #edf7f1;
      --muted: #91a09a;
      --green: #49e681;
      --green-dark: #1cab56;
      --food: #ff5369;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      overflow: auto;
      background:
        radial-gradient(circle at 50% 25%, #15221d 0, transparent 38%),
        var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    main {
      width: min(92vw, 540px);
      text-align: center;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 7vw, 3.4rem);
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .status {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin: 0 auto 10px;
      padding: 10px 14px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: rgba(17, 23, 32, 0.92);
      font-weight: 700;
    }

    #score {
      color: var(--green);
      font-variant-numeric: tabular-nums;
    }

    #state {
      color: var(--muted);
      font-size: 0.9rem;
    }

    #snake {
      display: block;
      width: min(92vw, 480px);
      height: min(92vw, 480px);
      min-width: 400px;
      min-height: 400px;
      max-width: 480px;
      max-height: 480px;
      margin: 0 auto;
      border: 2px solid var(--border);
      border-radius: 12px;
      background: #0b1016;
      box-shadow: 0 18px 55px rgba(0, 0, 0, 0.48);
    }

    .controls {
      display: flex;
      justify-content: center;
      gap: 10px;
      margin-top: 16px;
    }

    button {
      min-width: 94px;
      padding: 10px 16px;
      border: 1px solid #344253;
      border-radius: 9px;
      background: #18212c;
      color: var(--text);
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 100ms ease, background 100ms ease, border-color 100ms ease;
    }

    button:hover {
      border-color: var(--green-dark);
      background: #202c38;
    }

    button:active {
      transform: translateY(1px);
    }

    #start {
      border-color: #238e4b;
      background: #176535;
    }

    #start:hover {
      background: #1b7840;
    }

    .hint {
      margin: 13px 0 0;
      color: var(--muted);
      font-size: 0.88rem;
    }

    @media (max-width: 450px) {
      body {
        display: block;
        padding: 18px 8px;
      }

      main {
        min-width: 404px;
        margin: 0 auto;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Snake</h1>

    <div class="status">
      <span>Score: <span id="score">0</span></span>
      <span id="state">Ready</span>
    </div>

    <canvas id="snake" width="480" height="480" aria-label="Snake game board"></canvas>

    <div class="controls">
      <button id="start" type="button">Start</button>
      <button id="pause" type="button">Pause</button>
      <button id="reset" type="button">Reset</button>
    </div>

    <p class="hint">Use the arrow keys to steer.</p>
  </main>

  <script>
    (() => {
      "use strict";

      const canvas = document.getElementById("snake");
      const ctx = canvas.getContext("2d");
      const scoreElement = document.getElementById("score");
      const stateElement = document.getElementById("state");

      const w = 20;
      const h = 20;
      const cellWidth = canvas.width / w;
      const cellHeight = canvas.height / h;
      const tickDelay = 105;

      const vectors = {
        up: [0, -1],
        down: [0, 1],
        left: [-1, 0],
        right: [1, 0]
      };

      const opposites = {
        up: "down",
        down: "up",
        left: "right",
        right: "left"
      };

      let segments;
      let foodPosition;
      let direction;
      let queuedDirection;
      let isAlive;
      let points;
      let timer = null;

      function sameCell(a, b) {
        return a[0] === b[0] && a[1] === b[1];
      }

      function randomFood() {
        const free = [];

        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            if (!segments.some(segment => segment[0] === x && segment[1] === y)) {
              free.push([x, y]);
            }
          }
        }

        foodPosition = free.length
          ? free[Math.floor(Math.random() * free.length)]
          : [-1, -1];
      }

      function roundedRect(x, y, width, height, radius) {
        const r = Math.min(radius, width / 2, height / 2);
        ctx.beginPath();
        ctx.roundRect(x, y, width, height, r);
      }

      function draw() {
        ctx.fillStyle = "#0b1016";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.strokeStyle = "rgba(255,255,255,0.032)";
        ctx.lineWidth = 1;
        ctx.beginPath();

        for (let x = 1; x < w; x++) {
          ctx.moveTo(x * cellWidth + 0.5, 0);
          ctx.lineTo(x * cellWidth + 0.5, canvas.height);
        }

        for (let y = 1; y < h; y++) {
          ctx.moveTo(0, y * cellHeight + 0.5);
          ctx.lineTo(canvas.width, y * cellHeight + 0.5);
        }

        ctx.stroke();

        if (
          foodPosition &&
          foodPosition[0] >= 0 && foodPosition[0] < w &&
          foodPosition[1] >= 0 && foodPosition[1] < h
        ) {
          const cx = (foodPosition[0] + 0.5) * cellWidth;
          const cy = (foodPosition[1] + 0.5) * cellHeight;
          const radius = Math.min(cellWidth, cellHeight) * 0.32;

          ctx.save();
          ctx.shadowColor = "rgba(255,83,105,0.8)";
          ctx.shadowBlur = 14;
          ctx.fillStyle = "#ff5369";
          ctx.beginPath();
          ctx.arc(cx, cy, radius, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();

          ctx.fillStyle = "#ff9aa7";
          ctx.beginPath();
          ctx.arc(cx - radius * 0.25, cy - radius * 0.25, radius * 0.22, 0, Math.PI * 2);
          ctx.fill();
        }

        segments.forEach((segment, index) => {
          const inset = index === 0 ? 2 : 3;
          const x = segment[0] * cellWidth + inset;
          const y = segment[1] * cellHeight + inset;
          const width = cellWidth - inset * 2;
          const height = cellHeight - inset * 2;

          ctx.fillStyle = index === 0 ? "#63f598" : "#28bd62";
          roundedRect(x, y, width, height, index === 0 ? 7 : 6);
          ctx.fill();

          if (index === 0) {
            drawEyes(segment);
          }
        });

        if (!isAlive) {
          ctx.fillStyle = "rgba(4,7,10,0.67)";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.fillStyle = "#ffffff";
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
          ctx.font = "700 34px system-ui, sans-serif";
          ctx.fillText("Game Over", canvas.width / 2, canvas.height / 2 - 12);
          ctx.fillStyle = "#aebbb5";
          ctx.font = "16px system-ui, sans-serif";
          ctx.fillText("Reset to play again", canvas.width / 2, canvas.height / 2 + 28);
        }

        scoreElement.textContent = String(points);
      }

      function drawEyes(head) {
        const cx = (head[0] + 0.5) * cellWidth;
        const cy = (head[1] + 0.5) * cellHeight;
        const facing = vectors[direction];
        const side = [-facing[1], facing[0]];
        const forward = 4.5;
        const spread = 5;

        ctx.fillStyle = "#092014";

        for (const sideAmount of [-spread, spread]) {
          ctx.beginPath();
          ctx.arc(
            cx + facing[0] * forward + side[0] * sideAmount,
            cy + facing[1] * forward + side[1] * sideAmount,
            2.2,
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
      }

      function stopTimer() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
        }
      }

      function reset() {
        stopTimer();
        const centerX = Math.floor(w / 2);
        const centerY = Math.floor(h / 2);

        segments = [
          [centerX, centerY],
          [centerX - 1, centerY],
          [centerX - 2, centerY],
          [centerX - 3, centerY]
        ];
        direction = "right";
        queuedDirection = "right";
        isAlive = true;
        points = 0;
        randomFood();
        stateElement.textContent = "Ready";
        draw();
      }

      function tick() {
        if (!isAlive) {
          return;
        }

        direction = queuedDirection;
        const movement = vectors[direction];
        const head = segments[0];
        const nextHead = [head[0] + movement[0], head[1] + movement[1]];
        const ate = sameCell(nextHead, foodPosition);

        const hitWall =
          nextHead[0] < 0 ||
          nextHead[0] >= w ||
          nextHead[1] < 0 ||
          nextHead[1] >= h;

        const bodyToCheck = ate ? segments : segments.slice(0, -1);
        const hitBody = bodyToCheck.some(segment => sameCell(segment, nextHead));

        if (hitWall || hitBody) {
          isAlive = false;
          stopTimer();
          stateElement.textContent = "Game Over";
          draw();
          return;
        }

        segments.unshift(nextHead);

        if (ate) {
          points++;
          randomFood();
        } else {
          segments.pop();
        }

        draw();
      }

      function setDir(nextDirection) {
        if (!Object.prototype.hasOwnProperty.call(vectors, nextDirection)) {
          return;
        }

        if (opposites[direction] === nextDirection) {
          return;
        }

        queuedDirection = nextDirection;
      }

      function setFood(x, y) {
        foodPosition = [Number(x), Number(y)];
        draw();
      }

      function start() {
        if (!isAlive || timer !== null) {
          return;
        }

        stateElement.textContent = "Playing";
        timer = setInterval(tick, tickDelay);
      }

      function pause() {
        if (!isAlive) {
          return;
        }

        stopTimer();
        stateElement.textContent = "Paused";
      }

      document.getElementById("start").addEventListener("click", start);
      document.getElementById("pause").addEventListener("click", pause);
      document.getElementById("reset").addEventListener("click", reset);

      window.addEventListener("keydown", event => {
        const keyDirections = {
          ArrowUp: "up",
          ArrowDown: "down",
          ArrowLeft: "left",
          ArrowRight: "right"
        };

        const nextDirection = keyDirections[event.key];

        if (nextDirection) {
          event.preventDefault();
          setDir(nextDirection);
        }
      });

      window.game = {
        w,
        h,
        reset,
        tick,
        setDir,
        setFood,
        snake: () => segments.map(segment => [...segment]),
        food: () => [...foodPosition],
        alive: () => isAlive,
        score: () => points
      };

      reset();
    })();
  </script>
</body>
</html>
